// Node "Page modifiée" (Code, run once for all items).
// Input: the call made by the Notion automation "Statut modifié" of "Devis à suivre"
// (Send webhook). Only the page id is kept: the next node reads the page again from
// Notion, so a late, repeated or forged call can only make n8n look at what Notion
// holds now. Notion does not document the payload; the page is expected in
// body.data (a page object), with a search of the whole payload as a fallback.
// No page found: the run fails, so the Error Workflow reports it.

const UUID = /^[0-9a-f]{8}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{12}$/i;

function findPageId(payload) {
  for (const candidate of [payload?.data?.id, payload?.data?.page_id, payload?.page_id]) {
    if (typeof candidate === 'string' && UUID.test(candidate)) return candidate;
  }
  const stack = [payload];
  while (stack.length) {
    const node = stack.pop();
    if (!node || typeof node !== 'object') continue;
    if (node.object === 'page' && typeof node.id === 'string' && UUID.test(node.id)) return node.id;
    stack.push(...Object.values(node));
  }
  return null;
}

const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const payload = item.json.body ?? item.json;
  const pageId = findPageId(payload);
  if (!pageId) {
    throw new Error(`Appel du webhook sans page Notion reconnaissable : ${JSON.stringify(payload).slice(0, 300)}`);
  }
  const key = pageId.replace(/-/g, '').toLowerCase();
  if (!seen.has(key)) {
    seen.add(key);
    out.push({ json: { page_id: pageId } });
  }
}
return out;

// Node "Préparer les changements" (Code, run once for all items).
// Input, one of:
//   - the page read again after the Notion webhook "Statut modifié" (a page object);
//   - the hourly catch-up: the "Devis à suivre" rows whose "À envoyer à Furious" is
//     checked (a list of pages), i.e. changes the webhook missed (n8n down, Furious
//     not answering, automation paused by Notion after a failed call).
// Keeps the rows of "Devis à suivre" whose status waits for Furious: in scope,
// "Statut Furious" known, "Statut" different from it and not "gagné" (Notion only).
// The same test as the formula "À envoyer à Furious"; it also ignores the webhook
// calls caused by the sync or by n8n itself (then "Statut" = "Statut Furious").
// "Perdu : <raison>" (one status per Furious loss reason, decided 2026-09-30) marks
// the devis lost with that reason; plain "Perdu" is refused (no reason).
// Output: one item per such row. action "envoyer": the Furious pipe (and loss reason)
// and the query that reads the devis. action "annuler": status put back, reason in a
// comment.
// Queries and bodies are built here because they contain "}}", which ends an n8n
// expression.

const FOLLOWUP = ['2ced927802d7802a8642000be714240f', '2ced927802d780e38768e9c9fbeb5815'];   // data source, database
const NOTION_ONLY = ['gagné'];
const PIPES = {
  'brief': 5,
  'en cours': 0,
  'envoyée(s) attente réponse': 4,
  'envoyée(s) en attente de réponse': 4,
};
// Furious loss reasons (tag ids read from the lost devis on 2026-09-30), by the text
// after "Perdu :" in the Notion status. Compared without accents, case or extra spaces.
const LOSS_REASONS = {
  'budget trop élevé': 9,
  'sans réponse du client': 42,
  'projet abandonné': 25,
  'concurrent retenu': 19,
  'garde son prestataire': 155,
  'groupement': 224,
  'doublon': 37,
  'on ne se positionne pas': 50,
  'réponse trop tardive': 211,
  'autre': 20,
};
const LOST_PIPE = 1;

const plain = (prop) => (prop?.rich_text ?? prop?.title ?? []).map((part) => part?.plain_text ?? '').join('').trim();
const key = (name) => String(name ?? '').normalize('NFC').trim().toLowerCase();
const fold = (text) => String(text ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[\u2019\u2018]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase();
const REASON_BY_FOLDED = Object.fromEntries(Object.entries(LOSS_REASONS).map(([text, id]) => [fold(text), id]));
const LOSS_CHOICES = Object.keys(LOSS_REASONS).map((text) => `« Perdu : ${text} »`).join(', ');

// { pipe, lost_reason_id } for a status, { refusal } when it cannot be sent, null when unknown.
function target(statut) {
  const pipe = PIPES[key(statut)];
  if (pipe !== undefined) return { pipe };
  const lost = fold(statut).match(/^perdu\s*(?::\s*(.*))?$/);
  if (!lost) return null;
  const reasonId = REASON_BY_FOLDED[fold(lost[1] ?? '')];
  if (reasonId) return { pipe: LOST_PIPE, lost_reason_id: reasonId };
  return { refusal: `pour un devis perdu, choisir la raison dans le statut : ${LOSS_CHOICES}.` };
}
const compact = (id) => String(id ?? '').replace(/-/g, '').toLowerCase();

// The Notion writes of a row: "Statut Furious" confirmed, or "Statut" put back to
// what Furious has; the comment that says why a change was put back.
function notionBody(row, { confirm = false, revert = false }) {
  const properties = {};
  if (confirm) properties['Statut Furious'] = { select: { name: row.statut } };
  if (revert && row.statut_furious) properties['Statut'] = { status: { name: row.statut_furious } };
  return { properties };
}
function commentBody(row, reason) {
  const text = `🔁 Statut remis à « ${row.statut_furious} » : ${reason}`;
  return { parent: { page_id: row.page_id }, rich_text: [{ type: 'text', text: { content: text.slice(0, 1900) } }] };
}

const pages = [];
for (const item of $input.all()) {
  const json = item.json ?? {};
  if (Array.isArray(json.results)) pages.push(...json.results);
  else if (json.object === 'page') pages.push(json);
}

const out = [];
for (const page of pages) {
  const parent = page.parent ?? {};
  if (![parent.data_source_id, parent.database_id].some((id) => FOLLOWUP.includes(compact(id)))) continue;
  if (page.in_trash || page.archived) continue;
  const props = page.properties ?? {};
  const row = {
    page_id: page.id,
    devis_id: plain(props['ID Devis']),
    titre: plain(props['Name']),
    statut: props['Statut']?.status?.name ?? '',
    statut_furious: props['Statut Furious']?.select?.name ?? '',
  };
  const inScope = props['Dans le périmètre']?.checkbox === true;
  if (!inScope || !row.statut_furious || row.statut === row.statut_furious || NOTION_ONLY.includes(key(row.statut))) continue;

  const wanted = target(row.statut);
  row.pipe_cible = wanted?.pipe ?? null;
  if (wanted?.lost_reason_id) row.lost_reason_id = wanted.lost_reason_id;
  let refusal = '';
  if (!/^\d+$/.test(row.devis_id)) {
    refusal = "pas d'ID Devis sur cette ligne.";
  } else if (wanted?.refusal) {
    refusal = wanted.refusal;
  } else if (row.pipe_cible === null) {
    refusal = `« ${row.statut} » ne se choisit pas dans Notion : un devis signé se passe en gagné dans Furious. `
      + 'Dans Notion : brief, en cours, envoyée(s) attente réponse, gagné en attendant la signature, ou Perdu : raison.';
  }
  if (refusal) {
    out.push({ json: { ...row, action: 'annuler', notion_body: notionBody(row, { revert: true }),
                       comment_body: commentBody(row, refusal) } });
    continue;
  }
  const query = `{ Proposal(limit: 1, offset: 0, filter: {id: {eq: "${row.devis_id}"}})`
    + '{ id, statut, pipe, cf_bu, cf_typologie_de_devis, cf_typologie_myrium } }';
  out.push({ json: { ...row, action: 'envoyer', furious_query: query } });
}
return out;

// Node "Devis à envoyer" (Code, run once for all items).
// Runs after "Furious : connexion" (one login per run). Returns the rows of the
// true branch of "À envoyer à Furious ?" with action "envoyer" when the login
// worked. When Furious refuses the login (wrong or expired password in the n8n
// credential), the rows get action "connexion_refusee": their status is put back,
// a comment says why, and the run stops in error (e-mail from the Error Workflow).
// Nothing retries the login every hour then: repeated failures could lock the
// Furious account, which the Myrium sync uses too. When Furious does not answer,
// the run fails and the rows stay pending for the hourly catch-up.

const REASON = "n8n ne peut plus se connecter à Furious (identifiants à mettre à jour dans n8n). "
  + 'Changer le statut dans Furious en attendant.';

function notionBody(row, { confirm = false, revert = false }) {
  const properties = {};
  if (confirm) properties['Statut Furious'] = { select: { name: row.statut } };
  if (revert && row.statut_furious) properties['Statut'] = { status: { name: row.statut_furious } };
  return { properties };
}
function commentBody(row, reason) {
  const text = `🔁 Statut remis à « ${row.statut_furious} » : ${reason}`;
  return { parent: { page_id: row.page_id }, rich_text: [{ type: 'text', text: { content: text.slice(0, 1900) } }] };
}

const login = $('Furious : connexion').first().json ?? {};
const rows = $('À envoyer à Furious ?').all(0).map((item) => item.json);
const status = login.statusCode;

if (login.error || !status || status >= 500 || status === 408 || status === 429) {
  const why = status ?? login.error?.message ?? 'pas de réponse';
  throw new Error(`Furious ne répond pas à la connexion (${why}) : nouvel essai au rattrapage de l'heure.`);
}
if (login.body?.success === true && login.body?.token) {
  return rows.map((row) => ({ json: { ...row, action: 'envoyer' } }));
}
return rows.map((row) => ({
  json: { ...row, action: 'connexion_refusee', notion_body: notionBody(row, { revert: true }),
          comment_body: commentBody(row, REASON) },
}));

// Node "Décider" (Code, run once for all items).
// Input: the answers of "Furious : lire le devis", paired with the rows of the true
// branch of "Connexion acceptée ?". For each devis, compares what Furious has now
// with the status chosen in Notion:
//   maj        Furious must change: the update body is prepared (item goes on)
//   a_jour     Furious already has that status: "Statut Furious" is confirmed
//   annuler    the change cannot be made: status put back, reason in a comment
//   (none)     Furious did not answer: nothing written, the row stays pending and
//              the hourly catch-up tries again
// Every update re-sends the three custom fields of the devis (Furious refuses an
// update without them). "Typologie Myrium" has three options, "PA <= 15 000€",
// "CH >= 15 000€" and "PA"; the API cuts a value at "<", so "PA <= 15 000€" is read
// back as "PA " (with its space) while the option "PA" reads "PA". A value that
// cannot be told apart is never sent.
// A loss ("Perdu : <raison>") is sent as pipe 1 with the Furious loss reason; a devis
// already lost in Furious is only confirmed.

const WAITING = { '5': 'Brief', '0': 'En cours', '4': 'Envoyée(s) attente réponse' };
const LOST_PIPE = '1';

function typologieMyrium(read) {
  const raw = String(read ?? '');
  const text = raw.trim().toUpperCase();
  if (!text) return { value: null };
  if (text.startsWith('CH')) return { value: 'CH >= 15 000€' };
  if (text === 'PA' && raw === raw.trimEnd()) return { value: 'PA' };
  if (text.startsWith('PA')) return { value: 'PA <= 15 000€' };
  return { unknown: raw.trim() };
}

const decode = (text) => String(text ?? '')
  .replace(/&#0*39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const first = (value) => (Array.isArray(value) ? value[0] : value);
const pairedIndex = (item, i) => {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  return typeof paired?.item === 'number' ? paired.item : i;
};
const transient = (res) => Boolean(res?.error) || !res?.statusCode || res.statusCode >= 500
  || [401, 403, 408, 429].includes(res.statusCode) || typeof res.body !== 'object' || res.body === null;

function notionBody(row, { confirm = false, revert = false }) {
  const properties = {};
  if (confirm) properties['Statut Furious'] = { select: { name: row.statut } };
  if (revert && row.statut_furious) properties['Statut'] = { status: { name: row.statut_furious } };
  return { properties };
}
function commentBody(row, reason) {
  const text = `🔁 Statut remis à « ${row.statut_furious} » : ${reason}`;
  return { parent: { page_id: row.page_id }, rich_text: [{ type: 'text', text: { content: text.slice(0, 1900) } }] };
}

const rows = $('Connexion acceptée ?').all(0);
const out = [];
const settle = (row, action, { confirm = false, revert = false, reason = '' } = {}) => {
  const json = { ...row, action, notion_body: notionBody(row, { confirm, revert }) };
  if (reason) json.comment_body = commentBody(row, reason);
  out.push({ json });
};

$input.all().forEach((item, i) => {
  const row = { ...rows[pairedIndex(item, i)].json };
  const res = item.json ?? {};
  const found = res.body?.data?.Proposal;
  if (transient(res) || !Array.isArray(found)) return;   // pending: the hourly catch-up tries again

  const proposal = found.find((p) => String(p?.id ?? '') === row.devis_id);
  if (!proposal) return settle(row, 'annuler', { revert: true, reason: `devis ${row.devis_id} introuvable dans Furious.` });
  const pipe = String(proposal.pipe ?? '');
  if (row.pipe_cible === Number(LOST_PIPE) && pipe === LOST_PIPE) return settle(row, 'a_jour', { confirm: true });
  if (!(pipe in WAITING)) {
    return settle(row, 'annuler', {
      revert: true,
      reason: `ce devis est déjà « ${decode(proposal.statut) || pipe} » dans Furious (la synchro du matin mettra la ligne à jour).`,
    });
  }
  if (Number(pipe) === row.pipe_cible) return settle(row, 'a_jour', { confirm: true });

  const customFields = [];
  const bu = decode(first(proposal.cf_bu)).trim();
  if (bu) customFields.push({ name: 'bu', value: bu });
  const typologies = (Array.isArray(proposal.cf_typologie_de_devis)
    ? proposal.cf_typologie_de_devis
    : String(proposal.cf_typologie_de_devis ?? '').split(/\|#\||,/))
    .map((value) => decode(value).trim()).filter(Boolean);
  if (typologies.length) customFields.push({ name: 'typologie_de_devis', value: typologies });
  const myrium = typologieMyrium(decode(first(proposal.cf_typologie_myrium)));
  if (myrium.unknown) {
    return settle(row, 'annuler', {
      revert: true,
      reason: `Typologie Myrium « ${myrium.unknown} » inconnue de l'automatisation, changer le statut dans Furious.`,
    });
  }
  if (myrium.value) customFields.push({ name: 'typologie_myrium', value: myrium.value });
  const data = { id: Number(row.devis_id), pipe: row.pipe_cible };
  if (row.lost_reason_id) data.lost_reason_id = row.lost_reason_id;
  out.push({
    json: {
      ...row,
      action: 'maj',
      statut_furious_actuel: WAITING[pipe],
      furious_body: { action: 'update', data: { ...data, custom_fields: customFields } },
    },
  });
});
return out;

// Node "Lire la réponse de Furious" (Code, run once for all items).
// Input: the answers of "Furious : changer le statut", paired with the rows of the
// true branch of "Mettre à jour Furious ?". Furious answers HTTP 200 in both cases:
// {"success": true, "id": ...} when the status changed, {"success": false,
// "message": [...]} when it refused (e.g. "BU est requis", "Pipe invalide").
//   ok        "Statut Furious" confirmed; for a loss also "Perdu le" = today (Paris):
//             Furious keeps the old devis date when a devis is lost through its API,
//             Myrium uses this day as the loss date in "Devis perdus"
//   annuler   refused: status put back, Furious's reason in a comment
//   (none)    no usable answer: nothing written, the row stays pending; the hourly
//             catch-up reads the devis again, so an update that did go through is
//             only confirmed then

const decode = (text) => String(text ?? '')
  .replace(/&#0*39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const pairedIndex = (item, i) => {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  return typeof paired?.item === 'number' ? paired.item : i;
};
const transient = (res) => Boolean(res?.error) || !res?.statusCode || res.statusCode >= 500
  || [401, 403, 408, 429].includes(res.statusCode) || typeof res.body !== 'object' || res.body === null;

function reason(body) {
  const raw = body?.message ?? body?.error ?? '';
  const parts = (Array.isArray(raw) ? raw : [raw])
    .map((part) => decode(typeof part === 'string' ? part : (part?.message ?? JSON.stringify(part))).trim())
    .filter(Boolean);
  return parts.join(' ; ').slice(0, 600) || 'réponse inattendue';
}

function notionBody(row, { confirm = false, revert = false }) {
  const properties = {};
  if (confirm) properties['Statut Furious'] = { select: { name: row.statut } };
  if (revert && row.statut_furious) properties['Statut'] = { status: { name: row.statut_furious } };
  return { properties };
}
function commentBody(row, text) {
  const content = `🔁 Statut remis à « ${row.statut_furious} » : ${text}`;
  return { parent: { page_id: row.page_id }, rich_text: [{ type: 'text', text: { content: content.slice(0, 1900) } }] };
}

function parisToday() {
  try {
    return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Paris' }).format(new Date());   // YYYY-MM-DD
  } catch (error) {
    return new Date().toISOString().slice(0, 10);
  }
}

const rows = $('Mettre à jour Furious ?').all(0);
const out = [];

$input.all().forEach((item, i) => {
  const { furious_body, ...row } = rows[pairedIndex(item, i)].json;
  const res = item.json ?? {};
  if (transient(res)) return;   // pending: the hourly catch-up tries again
  if (res.body.success === true) {
    const notion_body = notionBody(row, { confirm: true });
    if (row.pipe_cible === 1) notion_body.properties['Perdu le'] = { date: { start: parisToday() } };
    out.push({ json: { ...row, action: 'ok', notion_body } });
    return;
  }
  out.push({ json: { ...row, action: 'annuler', notion_body: notionBody(row, { revert: true }),
                     comment_body: commentBody(row, `Furious a refusé le changement (${reason(res.body)}).`) } });
});
return out;
